//! Optional CPU-only whisper.cpp CLI. Fixed arguments, no inference network code.
//! OS network isolation and crash-orphan cleanup remain release gates.
#[path="voice_helper.rs"]mod optional_helper;
#[cfg(feature="desktop")]pub use optional_helper::install as install_helper;
pub use optional_helper::remove as remove_helper;
use serde::{Serialize,Deserialize};
use sha2::{Digest,Sha256};
use std::{path::{Path,PathBuf},fs::{self,OpenOptions},io::{Read,Write},sync::{Mutex,OnceLock,Arc,atomic::{AtomicBool,Ordering}},time::{Duration,Instant},process::{Command,Stdio}};
use crate::no_window::NoWindow;
pub const ENGINE_REV:&str="a8d002cfd879315632a579e73f0148d06959de36";
pub const MODEL_REV:&str="5359861c739e955e79d9a303bcbc70fb988958b1";
pub const MODEL_SHA:&str="60ed5bc3dd14eea856493d334349b405782ddcaf0028d4b5df4088345fba2efe";
pub const MODEL_BYTES:u64=147951465;
pub const MODEL_URL:&str="https://huggingface.co/ggerganov/whisper.cpp/resolve/5359861c739e955e79d9a303bcbc70fb988958b1/ggml-base.bin";
#[derive(Clone,Serialize)]#[serde(rename_all="camelCase")]
pub struct VoiceState{pub id:String,pub phase:String,pub bytes:u64,pub total:u64,pub transcript:Option<String>,pub error:Option<String>}
struct Job{state:VoiceState,cancel:Arc<AtomicBool>}
static JOB:OnceLock<Mutex<Option<Job>>>=OnceLock::new();
fn slot()->&'static Mutex<Option<Job>>{JOB.get_or_init(||Mutex::new(None))}
pub fn preview_enabled()->bool{option_env!("SOMNIA_LOCAL_VOICE_PREVIEW")==Some("1")}
pub fn require_preview()->Result<(),String>{if preview_enabled(){Ok(())}else{Err("Local voice preview is disabled in this build".into())}}
fn language(value:&str)->Result<&str,String>{match value{"de"|"en"=>Ok(value),_=>Err("Unsupported voice language".into())}}
fn active(phase:&str)->bool{matches!(phase,"downloading"|"transcribing")}
fn begin(phase:&str,total:u64)->Result<(String,Arc<AtomicBool>),String>{require_owner()?;let mut slot=slot().lock().map_err(|_|"Voice busy")?;if slot.as_ref().is_some_and(|j|active(&j.state.phase)){return Err("Voice job active".into())}let id=uuid::Uuid::new_v4().to_string();let cancel=Arc::new(AtomicBool::new(false));*slot=Some(Job{state:VoiceState{id:id.clone(),phase:phase.into(),bytes:0,total,transcript:None,error:None},cancel:cancel.clone()});Ok((id,cancel))}
fn update(id:&str,phase:&str,bytes:u64,text:Option<String>,error:Option<String>){if let Ok(mut s)=slot().lock(){if let Some(j)=s.as_mut().filter(|j|j.state.id==id){j.state.phase=phase.into();j.state.bytes=bytes;j.state.transcript=text;j.state.error=error;}}}
pub fn poll(id:&str)->Result<VoiceState,String>{let s=slot().lock().map_err(|_|"Voice busy")?;s.as_ref().filter(|j|j.state.id==id).map(|j|j.state.clone()).ok_or("Voice job expired".into())}
pub fn cancel(id:&str)->Result<(),String>{let mut s=slot().lock().map_err(|_|"Voice busy")?;if let Some(j)=s.as_mut().filter(|j|j.state.id==id){j.cancel.store(true,Ordering::SeqCst);j.state.transcript=None;if !active(&j.state.phase){j.state.phase="cancelled".into();}Ok(())}else{Err("Voice job expired".into())}}
pub fn cancel_owned(){if let Ok(mut s)=slot().lock(){if let Some(j)=s.as_mut(){j.cancel.store(true,Ordering::SeqCst);j.state.transcript=None;}}}
fn cancelled(c:&AtomicBool)->Result<(),String>{if c.load(Ordering::SeqCst){Err("Voice job cancelled".into())}else{Ok(())}}
fn secure_dir(path:&Path)->Result<(),String>{fs::create_dir_all(path).map_err(|_|"Voice storage unavailable")?;if fs::symlink_metadata(path).map_err(|_|"Voice storage unavailable")?.file_type().is_symlink(){return Err("Voice storage must not be a link".into())}#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;fs::set_permissions(path,fs::Permissions::from_mode(0o700)).map_err(|_|"Voice storage permissions failed")?;}Ok(())}
fn private_file(path:&Path)->Result<std::fs::File,String>{let mut options=OpenOptions::new();options.write(true).create_new(true);#[cfg(unix)]{use std::os::unix::fs::OpenOptionsExt;options.mode(0o600);}options.open(path).map_err(|_|"Voice private file unavailable".into())}
pub fn file_hash(path:&Path)->Result<(u64,String),String>{let meta=fs::symlink_metadata(path).map_err(|_|"Voice artifact missing")?;if !meta.is_file()||meta.file_type().is_symlink(){return Err("Invalid voice artifact".into())}let mut file=std::fs::File::open(path).map_err(|_|"Voice artifact unreadable")?;let mut hash=Sha256::new();let mut buffer=[0u8;65536];loop{let n=file.read(&mut buffer).map_err(|_|"Voice artifact unreadable")?;if n==0{break}hash.update(&buffer[..n]);}Ok((meta.len(),format!("{:x}",hash.finalize())))}
fn model_path(data:&Path)->PathBuf{data.join("voice").join("ggml-base.bin")}
fn check_model(data:&Path)->Result<(),String>{let (bytes,sha)=file_hash(&model_path(data))?;if bytes!=MODEL_BYTES||sha!=MODEL_SHA{return Err("Voice model checksum mismatch".into())}Ok(())}
#[derive(Deserialize)]#[serde(deny_unknown_fields)]
struct HelperManifest{schema_version:u32,engine_revision:String,sha256:String,target_os:String,target_arch:String,license:String,dependencies_reviewed:bool,notices_sha256:String}
fn manifest_valid(m:&HelperManifest)->bool{m.schema_version==2&&m.dependencies_reviewed&&m.engine_revision==ENGINE_REV&&m.license=="MIT"&&m.target_os==std::env::consts::OS&&m.target_arch==std::env::consts::ARCH&&[&m.sha256,&m.notices_sha256].iter().all(|v|v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit()&&!b.is_ascii_uppercase()))}
fn helper(resource:&Path)->Result<PathBuf,String>{let root=resource.join("voice");let manifest_path=root.join("manifest.json");let meta=fs::symlink_metadata(&manifest_path).map_err(|_|"Voice helper not packaged in this build")?;if !meta.is_file()||meta.file_type().is_symlink()||meta.len()>4096{return Err("Invalid voice helper manifest".into())}let m:HelperManifest=serde_json::from_slice(&fs::read(manifest_path).map_err(|_|"Voice manifest unavailable")?).map_err(|_|"Invalid voice helper manifest")?;if !manifest_valid(&m){return Err("Voice helper build mismatch".into())}let (_,notices)=file_hash(&root.join("THIRD-PARTY-NOTICES.txt"))?;if notices!=m.notices_sha256{return Err("Voice license notices mismatch".into())}let path=root.join(if cfg!(windows){"whisper-cli.exe"}else{"whisper-cli"});let (bytes,sha)=file_hash(&path)?;if bytes==0||bytes>100_000_000||sha!=m.sha256{return Err("Voice helper checksum mismatch".into())}Ok(path)}
#[derive(Serialize)]#[serde(rename_all="camelCase")]
pub struct VoiceStatus{pub helper_ready:bool,pub model_ready:bool,pub model_bytes:u64,pub model_sha256:&'static str,pub model_revision:&'static str,pub model_url:&'static str,pub engine_revision:&'static str,pub storage_checked:bool,pub helper_asset:Option<optional_helper::Asset>,pub helper_present:bool}
pub fn status(data:&Path,_resource:&Path)->VoiceStatus{VoiceStatus{helper_ready:require_owner().is_ok()&&optional_helper::lookup(data).is_ok(),model_ready:check_model(data).is_ok(),model_bytes:MODEL_BYTES,model_sha256:MODEL_SHA,model_revision:MODEL_REV,model_url:MODEL_URL,engine_revision:ENGINE_REV,storage_checked:false,helper_asset:optional_helper::release(),helper_present:optional_helper::present(data)}}
#[cfg(feature="desktop")]
pub fn download(data:PathBuf,acknowledged:bool)->Result<String,String>{require_preview()?;if !acknowledged{return Err("Review license, checksum and network download first".into())}let (id,cancel)=begin("downloading",MODEL_BYTES)?;let key=id.clone();std::thread::spawn(move||{let result=download_inner(&data,&key,&cancel);match result{Ok(())=>update(&key,if cancel.load(Ordering::SeqCst){"cancelled"}else{"complete"},MODEL_BYTES,None,None),Err(e)=>update(&key,if cancel.load(Ordering::SeqCst){"cancelled"}else{"failed"},0,None,Some(e))}});Ok(id)}
#[cfg(feature="desktop")]
async fn network_step<T>(future:impl std::future::Future<Output=Result<T,reqwest::Error>>,cancel:&AtomicBool)->Result<T,String>{tokio::pin!(future);loop{cancelled(cancel)?;tokio::select!{result=&mut future=>return result.map_err(|_|"Voice download interrupted".into()),_=tokio::time::sleep(Duration::from_millis(100))=>{}}}}
#[cfg(feature="desktop")]
fn download_inner(data:&Path,id:&str,cancel:&AtomicBool)->Result<(),String>{let runtime=tokio::runtime::Builder::new_current_thread().enable_all().build().map_err(|_|"Voice download runtime failed")?;runtime.block_on(download_async(data,id,cancel))}
#[cfg(feature="desktop")]
async fn download_async(data:&Path,id:&str,cancel:&AtomicBool)->Result<(),String>{let dir=data.join("voice");secure_dir(&dir)?;if fs2::available_space(&dir).map_err(|_|"Voice model volume unavailable")?<MODEL_BYTES+64*1024*1024{return Err("Not enough space for speech model and headroom".into())}let part=dir.join(format!("model-{}.part",id));let result=(async{let mut file=private_file(&part)?;let client=reqwest::Client::builder().no_proxy().redirect(reqwest::redirect::Policy::custom(|attempt|{if attempt.previous().len()>3||attempt.url().scheme()!="https"||attempt.url().host_str().is_none_or(|h|!(h=="huggingface.co"||h.ends_with(".hf.co")||h.ends_with(".huggingface.co"))){attempt.stop()}else{attempt.follow()}})).connect_timeout(Duration::from_secs(10)).timeout(Duration::from_secs(900)).build().map_err(|_|"Voice download unavailable")?;let mut response=network_step(client.get(MODEL_URL).send(),cancel).await?;if !response.status().is_success(){return Err("Voice model source unavailable".into())}let mut hash=Sha256::new();let mut bytes=0u64;loop{cancelled(cancel)?;let Some(buffer)=network_step(response.chunk(),cancel).await? else{break};bytes+=buffer.len() as u64;if bytes>MODEL_BYTES{return Err("Voice download too large".into())}file.write_all(&buffer).map_err(|_|"Voice model disk write failed")?;hash.update(&buffer);update(id,"downloading",bytes,None,None);}if bytes!=MODEL_BYTES||format!("{:x}",hash.finalize())!=MODEL_SHA{return Err("Voice model checksum mismatch".into())}file.sync_all().map_err(|_|"Voice model disk sync failed")?;drop(file);cancelled(cancel)?;let path=model_path(data);if path.exists(){check_model(data)?;fs::remove_file(&part).map_err(|_|"Voice model cleanup failed")?;}else{fs::rename(&part,path).map_err(|_|"Voice model finalization failed")?;}Ok::<(),String>(())}).await;if result.is_err(){let _=fs::remove_file(part);}result}
pub fn wav(pcm:&[i16])->Result<Vec<u8>,String>{if pcm.is_empty()||pcm.len()>16000*120{return Err("Voice audio must be 16kHz mono PCM, at most two minutes".into())}let length=(pcm.len()*2)as u32;let mut bytes=Vec::with_capacity(44+length as usize);bytes.extend_from_slice(b"RIFF");bytes.extend_from_slice(&(36+length).to_le_bytes());bytes.extend_from_slice(b"WAVEfmt ");bytes.extend_from_slice(&16u32.to_le_bytes());bytes.extend_from_slice(&1u16.to_le_bytes());bytes.extend_from_slice(&1u16.to_le_bytes());bytes.extend_from_slice(&16000u32.to_le_bytes());bytes.extend_from_slice(&32000u32.to_le_bytes());bytes.extend_from_slice(&2u16.to_le_bytes());bytes.extend_from_slice(&16u16.to_le_bytes());bytes.extend_from_slice(b"data");bytes.extend_from_slice(&length.to_le_bytes());for sample in pcm{bytes.extend_from_slice(&sample.to_le_bytes());}Ok(bytes)}
pub fn transcribe(data:PathBuf,_resource:PathBuf,pcm:Vec<i16>,spoken_language:String)->Result<String,String>{require_preview()?;language(&spoken_language)?;let input=wav(&pcm)?;let executable=optional_helper::lookup(&data)?;check_model(&data)?;let (id,cancel)=begin("transcribing",input.len() as u64)?;let key=id.clone();std::thread::spawn(move||{let result=run(&data,&executable,&input,&key,&cancel,&spoken_language);match result{Ok(text)=>{if cancel.load(Ordering::SeqCst){update(&key,"cancelled",0,None,None)}else{update(&key,"complete",input.len()as u64,Some(text),None)}},Err(e)=>update(&key,if cancel.load(Ordering::SeqCst){"cancelled"}else{"failed"},0,None,Some(e))}});Ok(id)}
fn kill_tree(child:&mut std::process::Child){#[cfg(unix)]{unsafe{libc::kill(-(child.id() as i32),libc::SIGKILL);}}#[cfg(windows)]{let _=Command::new(PathBuf::from(std::env::var_os("SystemRoot").unwrap_or_else(||"C:\\Windows".into())).join("System32").join("taskkill.exe")).args(["/PID",&child.id().to_string(),"/T","/F"]).no_window().stdout(Stdio::null()).stderr(Stdio::null()).status();}let _=child.kill();let _=child.wait();}
fn run(data:&Path,executable:&Path,input:&[u8],id:&str,cancel:&AtomicBool,spoken_language:&str)->Result<String,String>{language(spoken_language)?;let voice=data.join("voice");secure_dir(&voice)?;let root=voice.join("jobs");secure_dir(&root)?;let dir=root.join(id);secure_dir(&dir)?;let result=(||{let path=dir.join("input.wav");let mut file=private_file(&path)?;file.write_all(input).map_err(|_|"Voice scratch write failed")?;drop(file);let output=dir.join("transcript");let mut command=Command::new(executable);command.args(["-m"]).arg(model_path(data)).args(["-f"]).arg(&path).args(["-l",spoken_language,"-ng","-np","-nt","-otxt","-of"]).arg(&output).current_dir(&dir).env_clear().stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::null()).no_window();#[cfg(windows)]if let Some(root)=std::env::var_os("SystemRoot"){command.env("SystemRoot",root);}#[cfg(unix)]{use std::os::unix::process::CommandExt;command.process_group(0);}cancelled(cancel)?;configure_parent_death(&mut command);
let mut child=command.spawn().map_err(|_|"Voice helper could not start")?;#[cfg(windows)]let _job=match VoiceWindowsJob::attach(&child){Ok(job)=>job,Err(e)=>{kill_tree(&mut child);return Err(e)}};let started=Instant::now();loop{if cancel.load(Ordering::SeqCst)||started.elapsed()>Duration::from_secs(180){kill_tree(&mut child);return Err("Voice transcription cancelled or timed out".into())}match child.try_wait(){Ok(Some(status))=>{if !status.success(){return Err("Voice helper failed".into())}break},Ok(None)=>std::thread::sleep(Duration::from_millis(50)),Err(_)=>{kill_tree(&mut child);return Err("Voice helper wait failed".into())}}}cancelled(cancel)?;let text_path=output.with_extension("txt");let meta=fs::symlink_metadata(&text_path).map_err(|_|"Voice helper produced no transcript")?;if !meta.is_file()||meta.file_type().is_symlink()||meta.len()>48000{return Err("Voice transcript exceeds limit".into())}let text=fs::read_to_string(text_path).map_err(|_|"Voice transcript unreadable")?;if text.trim().is_empty()||text.chars().count()>12000||text.contains('\0'){return Err("Voice transcript invalid or empty".into())}Ok(text)})();let cleanup=fs::remove_dir_all(dir);if cleanup.is_err(){return Err("Voice scratch cleanup failed".into())}result}
#[cfg(test)]mod tests{use super::*;#[test]fn wav_header_limits(){let bytes=wav(&[0,32767,-32768]).unwrap();assert_eq!(&bytes[..4],b"RIFF");assert_eq!(&bytes[8..12],b"WAVE");assert_eq!(bytes.len(),50);assert_eq!(&bytes[44..],&[0,0,255,127,0,128]);assert!(wav(&[]).is_err());assert!(wav(&vec![0;16000*120+1]).is_err());}#[test]fn pins_are_exact(){assert_eq!(MODEL_SHA.len(),64);assert_eq!(MODEL_REV.len(),40);assert_eq!(ENGINE_REV.len(),40);assert!(MODEL_URL.contains(MODEL_REV));}#[test]fn missing_artifacts_fail_closed(){let root=tempfile::tempdir().unwrap();assert!(!status(root.path(),root.path()).helper_ready);assert!(!status(root.path(),root.path()).model_ready);}}

