/// Startup-only cleanup. Never read or kill persisted PIDs. File lock prevents cross-instance sweeps.
static VOICE_LEASE:OnceLock<std::fs::File>=OnceLock::new();static VOICE_READY:AtomicBool=AtomicBool::new(false);
pub fn initialize(data:&Path)->Result<(),String>{let voice=data.join("voice");secure_dir(&voice)?;let path=voice.join("owner.lock");if path.exists()&&fs::symlink_metadata(&path).map_err(|_|"Voice lease unavailable")?.file_type().is_symlink(){return Err("Invalid voice lease".into())}let mut options=OpenOptions::new();options.read(true).write(true).create(true).truncate(false);#[cfg(unix)]{use std::os::unix::fs::OpenOptionsExt;options.mode(0o600).custom_flags(libc::O_NOFOLLOW);}let lock=options.open(path).map_err(|_|"Voice lease unavailable")?;fs2::FileExt::try_lock_exclusive(&lock).map_err(|_|"Voice data active in another instance")?;if VOICE_LEASE.set(lock).is_err(){return Err("Voice already initialized".into())}let jobs=voice.join("jobs");if jobs.exists(){if fs::symlink_metadata(&jobs).map_err(|_|"Voice jobs unavailable")?.file_type().is_symlink(){return Err("Invalid voice jobs directory".into())}fs::remove_dir_all(&jobs).map_err(|_|"Voice orphan scratch cleanup failed")?;}for entry in fs::read_dir(&voice).map_err(|_|"Voice cleanup unavailable")?{let entry=entry.map_err(|_|"Voice cleanup failed")?;let name=entry.file_name().to_string_lossy().into_owned();if name.starts_with("model-")&&name.ends_with(".part")&&entry.file_type().map_err(|_|"Voice cleanup failed")?.is_file(){fs::remove_file(entry.path()).map_err(|_|"Voice partial cleanup failed")?;}}optional_helper::cleanup_staging(data)?;VOICE_READY.store(true,Ordering::SeqCst);Ok(())}
pub fn require_owner()->Result<(),String>{if !VOICE_READY.load(Ordering::SeqCst){Err("Voice startup cleanup or ownership check unavailable".into())}else{Ok(())}}
#[cfg(windows)]struct VoiceWindowsJob(windows_sys::Win32::Foundation::HANDLE);
#[cfg(windows)]impl VoiceWindowsJob{fn attach(child:&std::process::Child)->Result<Self,String>{use std::os::windows::io::AsRawHandle;use windows_sys::Win32::System::JobObjects::*;unsafe{let handle=CreateJobObjectW(std::ptr::null(),std::ptr::null());if handle.is_null(){return Err("Voice job object unavailable".into())}let job=Self(handle);let mut info:JOBOBJECT_EXTENDED_LIMIT_INFORMATION=std::mem::zeroed();info.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;if SetInformationJobObject(handle,JobObjectExtendedLimitInformation,&info as *const _ as *const _,std::mem::size_of_val(&info)as u32)==0||AssignProcessToJobObject(handle,child.as_raw_handle()as _)==0{return Err("Voice job assignment failed".into())}Ok(job)}}}
#[cfg(windows)]impl Drop for VoiceWindowsJob{fn drop(&mut self){unsafe{windows_sys::Win32::Foundation::CloseHandle(self.0);}}}
#[cfg(test)]mod orphan_tests{use super::*;#[test]fn owned_stage_cleanup_preserves_model_and_installed_files(){let data=tempfile::tempdir().unwrap();let voice=data.path().join("voice");let stage=voice.join("helpers/stage-test");fs::create_dir_all(&stage).unwrap();fs::write(stage.join("partial"),b"x").unwrap();fs::write(voice.join("ggml-base.bin"),b"preserved").unwrap();optional_helper::cleanup_staging(data.path()).unwrap();assert!(!stage.exists());assert_eq!(fs::read(voice.join("ggml-base.bin")).unwrap(),b"preserved");}#[cfg(unix)]#[test]fn helper_stage_symlink_is_rejected(){use std::os::unix::fs::symlink;let data=tempfile::tempdir().unwrap();let outside=tempfile::tempdir().unwrap();let base=data.path().join("voice/helpers");fs::create_dir_all(&base).unwrap();symlink(outside.path(),base.join("stage-hostile")).unwrap();assert!(optional_helper::cleanup_staging(data.path()).is_err());assert!(outside.path().exists());}}

fn configure_parent_death(command:&mut Command){#[cfg(target_os="linux")]{use std::os::unix::process::CommandExt;let parent=std::process::id() as libc::pid_t;unsafe{command.pre_exec(move||{if libc::prctl(libc::PR_SET_PDEATHSIG,libc::SIGKILL)!=0{return Err(std::io::Error::last_os_error())}if libc::getppid()!=parent{return Err(std::io::Error::other("Voice parent exited"))}Ok(())});}}
}

#[cfg(test)]mod ci_tests{
 use super::*;
 /// Reexec worker is inert unless CI subprocess mode is explicitly present.
 #[test]fn process_worker(){if std::env::var("SOMNIA_VOICE_CI_MODE").ok().as_deref()!=Some("worker"){return}std::thread::sleep(Duration::from_secs(60));}
 #[test]fn process_owner(){if std::env::var("SOMNIA_VOICE_CI_MODE").ok().as_deref()!=Some("owner"){return}let pidfile=PathBuf::from(std::env::var_os("SOMNIA_VOICE_CI_PID").unwrap());let mut command=Command::new(std::env::current_exe().unwrap());command.args(["--exact","local_voice::ci_tests::process_worker","--nocapture"]).env("SOMNIA_VOICE_CI_MODE","worker");#[cfg(unix)]{use std::os::unix::process::CommandExt;command.process_group(0);}configure_parent_death(&mut command);let child=command.spawn().unwrap();#[cfg(windows)]let _job=VoiceWindowsJob::attach(&child).unwrap();fs::write(pidfile,child.id().to_string()).unwrap();std::thread::sleep(Duration::from_secs(60));}
 fn alive(pid:u32)->bool{#[cfg(unix)]{if let Ok(stat)=fs::read_to_string(format!("/proc/{pid}/stat")){if stat.split(')').nth(1).is_some_and(|rest|rest.trim_start().starts_with('Z')){return false}}unsafe{libc::kill(pid as i32,0)==0}}#[cfg(windows)]{use windows_sys::Win32::System::Threading::*;unsafe{let handle=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,0,pid);if handle.is_null(){return false}let mut code=0;let ok=GetExitCodeProcess(handle,&mut code);windows_sys::Win32::Foundation::CloseHandle(handle);ok!=0&&code==259}}}
 #[cfg(any(target_os="linux",windows))]#[test]fn parent_crash_kills_owned_direct_child(){let root=tempfile::tempdir().unwrap();let pidfile=root.path().join("worker.pid");let mut owner=Command::new(std::env::current_exe().unwrap()).args(["--exact","local_voice::ci_tests::process_owner","--nocapture"]).env("SOMNIA_VOICE_CI_MODE","owner").env("SOMNIA_VOICE_CI_PID",&pidfile).spawn().unwrap();let deadline=Instant::now()+Duration::from_secs(10);while !pidfile.exists()&&Instant::now()<deadline{std::thread::sleep(Duration::from_millis(25));}if !pidfile.exists(){let _=owner.kill();let _=owner.wait();panic!("owner did not attach child protection")}let pid:u32=fs::read_to_string(pidfile).unwrap().parse().unwrap();assert!(alive(pid));owner.kill().unwrap();owner.wait().unwrap();let deadline=Instant::now()+Duration::from_secs(5);while alive(pid)&&Instant::now()<deadline{std::thread::sleep(Duration::from_millis(25));}if alive(pid){#[cfg(unix)]unsafe{libc::kill(pid as i32,libc::SIGKILL);}panic!("owned child survived abrupt parent exit");}}
}
#[cfg(test)]mod startup_ci_tests{use super::*;#[test]fn startup_worker(){let mode=std::env::var("SOMNIA_VOICE_STARTUP_MODE").unwrap_or_default();if mode.is_empty(){return}let data=PathBuf::from(std::env::var_os("SOMNIA_VOICE_DATA").unwrap());if mode=="contender"{assert!(initialize(&data).is_err());assert!(data.join("voice/jobs/active/marker").exists());return}initialize(&data).unwrap();assert!(!data.join("voice/jobs/stale").exists());assert_eq!(fs::read(data.join("voice/ggml-base.bin")).unwrap(),b"preserve");let active=data.join("voice/jobs/active");fs::create_dir_all(&active).unwrap();fs::write(active.join("marker"),b"active").unwrap();let status=Command::new(std::env::current_exe().unwrap()).args(["--exact","local_voice::startup_ci_tests::startup_worker","--nocapture"]).env("SOMNIA_VOICE_STARTUP_MODE","contender").env("SOMNIA_VOICE_DATA",&data).status().unwrap();assert!(status.success());assert!(active.join("marker").exists());}#[test]fn startup_cleanup_holds_exclusive_owner_and_preserves_model(){let data=tempfile::tempdir().unwrap();let stale=data.path().join("voice/jobs/stale");fs::create_dir_all(&stale).unwrap();fs::write(stale.join("audio.wav"),b"private fixture").unwrap();fs::write(data.path().join("voice/ggml-base.bin"),b"preserve").unwrap();let status=Command::new(std::env::current_exe().unwrap()).args(["--exact","local_voice::startup_ci_tests::startup_worker","--nocapture"]).env("SOMNIA_VOICE_STARTUP_MODE","owner").env("SOMNIA_VOICE_DATA",data.path()).status().unwrap();assert!(status.success());}}
